            link: .init(text: ThemeColor(red: 0, green: 0, blue: 0, alpha: 0)),
            highlight: .init(bg: ThemeColor(red: 0, green: 0, blue: 0, alpha: 0), radius: 0),
            overlay: .init(enterScale: 0, enterOffset: 0),
            skeleton: .init(fill: ThemeColor(red: 0, green: 0, blue: 0, alpha: 0), pillWidth: 0)),
        density: .default,
        reduceMotion: false,
        increaseContrast: false)

    /// A table from resolved values by registry key; nil if any token is missing or mistyped.
    init?(table t: [String: TokenValue], density: ThemeDensity) {
        var tokens = ThemeTokens.zero
        for key in Self.registryKeys {
            guard let value = t[key], tokens.set(value, forKey: key) else { return nil }
        }
        tokens.density = density
        self = tokens
    }

    /// A table from resolved values by registry key; missing or mistyped tokens come from `fallback`.
    init(table t: [String: TokenValue], fallback f: ThemeTokens, density: ThemeDensity) {
        self = f
        for (key, value) in t { set(value, forKey: key) }
        self.density = density
    }
}

extension ThemeTokens.Components {
    /// A component token's typed value by registry key (`components/row/unreadDot`), through its group.
    func value(forKey key: String) -> TokenValue? {
        let parts = key.split(separator: "/", maxSplits: 2)
        guard parts.count == 3, parts[0] == "components" else { return nil }
        switch parts[1] {
        case "window": return window.value(forKey: key)
        case "toolbar": return toolbar.value(forKey: key)
        case "footer": return footer.value(forKey: key)
        case "tab": return tab.value(forKey: key)
        case "row": return row.value(forKey: key)
        case "labelChip": return labelChip.value(forKey: key)
        case "swipe": return swipe.value(forKey: key)
        case "sidebar": return sidebar.value(forKey: key)
        case "labelSidebar": return labelSidebar.value(forKey: key)
        case "thread": return thread.value(forKey: key)
        case "avatar": return avatar.value(forKey: key)
        case "compose": return compose.value(forKey: key)
        case "token": return token.value(forKey: key)
        case "palette": return palette.value(forKey: key)
        case "picker": return picker.value(forKey: key)
        case "popover": return popover.value(forKey: key)
        case "modal": return modal.value(forKey: key)
        case "toast": return toast.value(forKey: key)
        case "banner": return banner.value(forKey: key)
        case "keycap": return keycap.value(forKey: key)
        case "focus": return focus.value(forKey: key)
        case "chip.ai": return chipAI.value(forKey: key)
        case "link": return link.value(forKey: key)
        case "highlight": return highlight.value(forKey: key)
        case "overlay": return overlay.value(forKey: key)
        case "skeleton": return skeleton.value(forKey: key)
        default: return nil
        }
    }
}

